const q=($input.first().json.query)||{};
const PASS='CHANGE_ME_ADMIN_PASS';
const ok=(String(q.pass||'')===PASS);
const esc=s=>String(s==null?'':s).replace(/'/g,"''");
let period=String(q.period||'month').toLowerCase(); if(['day','week','month','quarter','year'].indexOf(period)<0) period='month';
const dev=esc(q.device_id||''); const region=esc(q.region||'');
let where=[]; if(dev) where.push("s.device_id='"+dev+"'"); if(region) where.push("p.region='"+region+"'");
const W=where.length?(' WHERE '+where.join(' AND ')):'';
const base="FROM care_sessions s LEFT JOIN care_profiles p ON p.device_id=s.device_id"+W;
const qp="SELECT to_char(date_trunc('"+period+"', s.started_at AT TIME ZONE 'Asia/Seoul'),'YYYY-MM-DD') AS bucket, count(*) AS sessions, COALESCE(sum(s.duration_sec),0) AS duration, COALESCE(sum(s.total_tokens),0) AS tokens "+base+" GROUP BY 1";
const qr="SELECT COALESCE(NULLIF(p.region,''),'(미지정)') AS region, count(*) AS sessions, COALESCE(sum(s.duration_sec),0) AS duration, COALESCE(sum(s.total_tokens),0) AS tokens "+base+" GROUP BY 1";
const qd="SELECT s.device_id, COALESCE(NULLIF(p.name,''),'(이름없음)') AS name, COALESCE(NULLIF(p.region,''),'(미지정)') AS region, count(*) AS sessions, COALESCE(sum(s.duration_sec),0) AS duration, COALESCE(sum(s.total_tokens),0) AS tokens, to_char(max(s.started_at) AT TIME ZONE 'Asia/Seoul','MM-DD HH24:MI') AS last "+base+" GROUP BY 1,2,3";
const combined="SELECT (SELECT COALESCE(json_agg(t ORDER BY t.bucket),'[]') FROM ("+qp+") t) AS byperiod, (SELECT COALESCE(json_agg(t ORDER BY t.sessions DESC),'[]') FROM ("+qr+") t) AS byregion, (SELECT COALESCE(json_agg(t ORDER BY t.sessions DESC),'[]') FROM ("+qd+") t) AS bydevice";
const bad="SELECT '[]'::json AS byperiod, '[]'::json AS byregion, '[]'::json AS bydevice";
return [{ json:{ ok, period, device_id:dev, region, query: ok?combined:bad } }];

