const b=($input.first().json.body)||{};
if(String(b.key||'')!=='sysmetrics2026') return [{json:{query:"SELECT 1 WHERE false"}}];
const num=v=>{ const x=parseFloat(v); return isNaN(x)?'NULL':x; };
const esc=s=>String(s==null?'':s).replace(/'/g,"''");
const q="INSERT INTO sys_metrics (id,cpu,mem,disk,gpu,gpu_name,uptime,host,updated_at) VALUES (1,"+num(b.cpu)+","+num(b.mem)+","+num(b.disk)+","+num(b.gpu)+",'"+esc(b.gpu_name)+"',"+num(b.uptime)+",'"+esc(b.host)+"',now()) ON CONFLICT (id) DO UPDATE SET cpu=EXCLUDED.cpu,mem=EXCLUDED.mem,disk=EXCLUDED.disk,gpu=EXCLUDED.gpu,gpu_name=EXCLUDED.gpu_name,uptime=EXCLUDED.uptime,host=EXCLUDED.host,updated_at=now()";
return [{json:{query:q}}];

const q=($input.first().json.query)||{};
const ok=(String(q.pass||'')==='CHANGE_ME_ADMIN_PASS');
const sql="SELECT (SELECT cpu FROM sys_metrics WHERE id=1) AS cpu,(SELECT mem FROM sys_metrics WHERE id=1) AS mem,(SELECT disk FROM sys_metrics WHERE id=1) AS disk,(SELECT gpu FROM sys_metrics WHERE id=1) AS gpu,(SELECT gpu_name FROM sys_metrics WHERE id=1) AS gpu_name,(SELECT uptime FROM sys_metrics WHERE id=1) AS uptime,(SELECT host FROM sys_metrics WHERE id=1) AS host,(SELECT to_char(updated_at AT TIME ZONE 'Asia/Seoul','MM-DD HH24:MI:SS') FROM sys_metrics WHERE id=1) AS updated_at,(SELECT (EXTRACT(EPOCH FROM (now()-updated_at))<30) FROM sys_metrics WHERE id=1) AS fresh,(SELECT count(*) FROM care_profiles WHERE last_ping > now()-interval '45 seconds') AS active_calls,(SELECT count(*) FROM care_sessions WHERE started_at > now()-interval '1 hour') AS calls_1h,(SELECT COALESCE(sum(total_tokens),0) FROM care_sessions WHERE started_at > now()-interval '1 hour') AS tokens_1h";
return [{json:{ ok, query: ok?sql:"SELECT 1 WHERE false" }}];

let ok=false; try{ ok=$('시스템빌드').first().json.ok===true; }catch(e){}
if(!ok) return [{json:{error:'unauthorized'}}];
const r=$input.first().json||{};
